#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    // Maintain inv_buffer_contents invariant
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        if pre.tail - pre.buffer_size <= i < pre.tail {
            // Entry was already in the valid range before
            assert(pre.contents.contains_key(i) == 
                (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                 i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)));

            // After the transition, contents has been updated
            if i < pre.tail - pre.buffer_size {
                // This entry was withdrawn
                assert(!post.contents.contains_key(i));
                assert(!(log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                         i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)));
            } else {
                // This entry is preserved
                assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
                assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == 
                       log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat) == 
                       map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));
            }
        } else {
            // New entries added in the range [pre.tail, post.tail)
            assert(pre.tail <= i < post.tail);
            // These entries were not in pre.contents and should not satisfy the condition in pre state
            assert(!pre.contents.contains_key(i));
            // These entries were not alive in pre state
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            // After transition, these entries should be in contents according to the invariant logic
            // But wait! Looking closer at the transition, advance_tail_finish doesn't actually deposit
            // new entries. It just sets up the state for appending.
            assert(!post.contents.contains_key(i));
            // Since these entries don't exist in post.contents, we need to verify they don't meet the criteria
            assert(!(log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                     i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)));
        }
    };

    // For entries beyond tail, maintain the invariant that they don't exist
    assert forall |i: int| post.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
        if pre.tail <= i {
            assert(!pre.contents.contains_key(i));
            // Contents beyond tail are neither withdrawn nor deposited
            assert(!post.contents.contains_key(i));
        } else {
            // i < pre.tail, but also post.tail <= i, this is impossible
            assert(false);
        }
    };

    // Maintain all_combiner_valid invariant
    assert forall |n_id| #[trigger] post.combiner.contains_key(n_id) implies
        post.combiner_valid(n_id, post.combiner[n_id]) by {
        if n_id == node_id {
            // The combiner state changed for this node
            assert(post.combiner[n_id] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });
            // Verify that the Appending state meets the combiner_valid requirements
            assert(post.local_versions.contains_key(n_id));
            assert(post.local_versions[n_id] <= pre.tail <= new_tail); // cur_idx = pre.tail
            assert(new_tail <= post.tail); // tail unchanged in this step
            assert((post.tail as int) - (post.buffer_size as int) <= pre.tail <= (post.tail as int));
            // For all entries in range [cur_idx, tail), they should not be alive
            assert forall |j: nat| pre.tail <= j < new_tail implies 
                !(log_entry_is_alive(post.alive_bits, j as int, post.buffer_size)) by {
                // Need to prove the alive bits are correctly maintained
                // Looking at the transition, we didn't change any alive bits yet
                // The withdrawn entries might affect this claim
                assert(log_entry_is_alive(post.alive_bits, j as int, post.buffer_size) == 
                       log_entry_is_alive(pre.alive_bits, j as int, pre.buffer_size));

                // From the withdraw operation in the transition:
                // we withdrew contents in range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
                // The alive check for j should depend on whether j falls in that range and how that affects the mapping

                // Let's consider what we know from pre-state
                assert(pre.combiner_valid(n_id, pre.combiner[n_id])); // Was Idle, valid trivially
            };
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        } else if post.combiner.contains_key(n_id) {
            // Other combiner states remain unchanged
            assert(post.combiner[n_id] === pre.combiner[n_id]);
            assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        }
    };
}

