                    // The withdrawn entries might affect this claim
                    assert(log_entry_is_alive(post.alive_bits, j as int, post.buffer_size) == 
                           log_entry_is_alive(pre.alive_bits, j as int, pre.buffer_size));

                    // From the withdraw operation in the transition:
                    // we withdrew contents in range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
                    // The alive check for j should depend on whether j falls in that range and how that affects the mapping

                    // Let's consider what we know from pre-state
                    assert(pre.combiner_valid(n_id, pre.combiner[n_id])); // Was Idle, valid trivially
                };
                assert(post.combiner_valid(n_id, post.combiner[n_id]));
            } else if post.combiner.contains_key(n_id) {
                // Other combiner states remain unchanged
                assert(post.combiner[n_id] === pre.combiner[n_id]);
                assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
