#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    let withdrawn_range_start = pre.tail - pre.buffer_size;
    let withdrawn_range_end = new_tail - pre.buffer_size;

    // Maintain inv_buffer_contents invariant
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // The post range is [new_tail - buffer_size, new_tail)
        assert(post.tail - post.buffer_size == new_tail - post.buffer_size);

        if i < pre.tail - pre.buffer_size {
            // These entries are before the withdrawn range
            assert(i < withdrawn_range_start);
            // They should be preserved
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == 
                   log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            // By pre invariant:
            assert(pre.contents.contains_key(i) == 
                (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                 i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)));
            // Local versions unchanged:
            assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat) == 
                   map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));
            // Therefore post condition holds
        } else if i < new_tail - pre.buffer_size {
            // These entries are in the withdrawn range [pre.tail - buffer_size, new_tail - buffer_size)
            assert(withdrawn_range_start <= i < withdrawn_range_end);
            // They were withdrawn from contents
            assert(!post.contents.contains_key(i));
            // Show they don't satisfy the positive condition
            // Need to show that either they're not alive OR they're >= min_local_head 
            // Actually, they should not be in contents, so they should NOT satisfy the disjunction
            assert(!(log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                     i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)));
        } else {
            // These entries are in [new_tail - buffer_size, new_tail) and are >= pre.tail
            // No new deposits happen in this transition, so they're not in contents
            assert(new_tail - pre.buffer_size <= i < new_tail);
            assert(!post.contents.contains_key(i));
            // Need to show they don't satisfy the positive condition
            assert(!(log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                     i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)));
        }
    };

    // For entries beyond tail, maintain the invariant that they don't exist
    assert forall |i: int| post.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
        // post.tail is new_tail
        assert(post.tail == new_tail);
        // pre.contents doesn't contain anything >= pre.tail
        // post.contents only differs from pre.contents by withdrawing some entries
        // None of which would be >= new_tail since we only withdrew entries < new_tail - buffer_size
        // Actually, let's think carefully:
        // pre.contents contains keys i such that -pre.buffer_size <= i < pre.tail
        // post.contents contains keys i such that -post.buffer_size <= i < post.tail 
        // but some entries in [pre.tail - pre.buffer_size, new_tail - pre.buffer_size) were removed
        // So post.contents contains keys i such that -pre.buffer_size <= i < pre.tail - pre.buffer_size UNION
        //                                               [new_tail - pre.buffer_size, pre.tail)  UNION
        //                                               [pre.tail, new_tail)
        // Wait, no, that's wrong. The withdrawal was from [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)

        // Actually, simpler: post.contents is pre.contents minus the withdrawn entries
        // withdrawn entries were from [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
        // For i >= new_tail, they were not in pre.contents anyway (since pre.contents has keys < pre.tail)
        // So they shouldn't be in post.contents
    };

    // Maintain all_combiner_valid invariant
    assert forall |n_id| #[trigger] post.combiner.contains_key(n_id) implies
        post.combiner_valid(n_id, post.combiner[n_id]) by {
        if n_id == node_id {
            // The combiner state changed for this node to Appending { cur_idx: pre.tail, tail: new_tail }
            assert(post.combiner[n_id] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });

            // Check CombinerState::Appending validity conditions:
            // 1. self.local_versions[node_id] <= cur_idx <= tail  
            assert(post.local_versions.contains_key(node_id));
            assert(post.local_versions[node_id] <= pre.tail <= new_tail);

            // 2. tail <= self.tail
            assert(new_tail <= post.tail);
            assert(post.tail == new_tail);

            // 3. (self.tail as int) - (self.buffer_size as int) <= cur_idx <= (self.tail as int)
            assert((new_tail as int) - (post.buffer_size as int) <= pre.tail <= (new_tail as int));

            // 4. All entries in [cur_idx, tail) are not alive
            assert forall |i: nat| pre.tail <= i < new_tail implies 
                !(log_entry_is_alive(post.alive_bits, i as int, post.buffer_size)) by {
                // Need to prove these entries are not alive.
                // In the transition, no alive_bits changes happened, so alive_bits unchanged.
                // These entries were in the valid index range already, so they exist in pre state.
                // They weren't among the withdrawn entries (which are < pre.tail).
                // The invariant says that currently existing content follows certain patterns.
                // Entries in [pre.tail, new_tail) were not in pre.contents, meaning they didn't 
                // satisfy the positive criterion in pre state.
                assert(!pre.contents.contains_key(i as int));
                assert(pre.contents.contains_key(i as int) ==  
                    (log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size) ||
                     i as int < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)));
                // So they do NOT satisfy the condition, proving the antecedent is false,
                // which makes the consequent also false (they're not alive), which proves the goal.
            };
        } else {
            // Other combiner states remain unchanged
            assert(post.combiner[n_id] === pre.combiner[n_id]);
            assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        }
    };
}

