                assert(pre.combiner_valid(n_id, pre.combiner[n_id])); // Was Idle, valid trivially
            };
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        } else if post.combiner.contains_key(n_id) {
            // Other combiner states remain unchanged
            assert(post.combiner[n_id] === pre.combiner[n_id]);
            assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        }
    };
}

