#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    // Maintain inv_buffer_contents invariant
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // Post state contains entries in range [new_tail - buffer_size, new_tail)
        assert(post.tail == new_tail);
        assert(post.buffer_size == pre.buffer_size);

        // In the transition, we withdrew entries in range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
        let withdrawn_start = pre.tail - pre.buffer_size;
        let withdrawn_end = new_tail - pre.buffer_size;

        // Case analysis based on where i falls relative to the withdrawn range:

        // Case 1: i is before the withdrawn range
        if i < withdrawn_start {
            assert(i < pre.tail - pre.buffer_size);
            // These entries are unchanged
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            assert(map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)) == map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat)));
            // By pre invariant
            assert(pre.contents.contains_key(i) == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || i < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))));
            // Hence equivalence holds for post
        }
        // Case 2: i is in the withdrawn range
        else if i < withdrawn_end {
            assert(withdrawn_start <= i < withdrawn_end);
            // These entries were explicitly withdrawn, so they're not in post.contents
            assert(!post.contents.contains_key(i));
            // Must show they also do NOT satisfy the condition
            // That means showing BOTH: not alive AND not < min_local_head
            // But it's sufficient to show that the disjunction is false
            // TODO: actually finish this proof properly
            assert(pre.contents.contains_key(i));  // By pre.inv_buffer_contents since i is in [pre.tail - buffer_size, pre.tail)
            assert(pre.contents.contains_key(i) == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || i < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))));
            // But in post, this entry is not in contents, yet alive_bits unchanged for this i...
            // Hmmm, I think I need a better understanding of what withdrawn means...
        }
        // Case 3: i is after the withdrawn range but before new_tail
        else {
            assert(withdrawn_end <= i < new_tail);
            assert(new_tail - pre.buffer_size <= i < new_tail);
            // These entries are newly in range but no new deposit happened
            assert(!post.contents.contains_key(i));
            // Again, must show the disjunction is false in post state
        }
    };

