    fn advance_head_abort_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(advance_head_finish)]
    fn advance_head_finish_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(advance_tail_start)]
    fn advance_tail_start_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(advance_tail_abort)]
    fn advance_tail_abort_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(advance_tail_finish)]
    fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
        // Maintain inv_buffer_contents invariant
        assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
            (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                i < map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)))
            <==>
            #[trigger] post.contents.contains_key(i)
        ) by {
            // Post state has tail = new_tail, so the range is [new_tail - buffer_size, new_tail)

            // Pre state contained entries in [-buffer_size, pre.tail)
            // Post state will contain entries in [-buffer_size, pre.tail - buffer_size) U [new_tail - buffer_size, pre.tail) U [pre.tail, new_tail)
            // But wait, that doesn't make sense because in the withdraw statement we removed
            // entries [pre.tail - buffer_size, new_tail - buffer_size) from the contents (and put them in 'withdrawn').
            // So post.contents = pre.contents - withdrawn_entries

            let withdrawn_start = pre.tail - pre.buffer_size;
            let withdrawn_end = new_tail - pre.buffer_size;

            // Three cases for where i can be w.r.t. the withdrawn range:
            if i < withdrawn_start {
                // These entries (< pre.tail - buffer_size) are not affected by withdrawal
                assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
                assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                // map_min_value is unchanged
                assert(map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)) == map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat)));
                // Apply the pre-condition invariant
                assert(pre.contents.contains_key(i) == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || 
                                                        i < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))));
                // So for post it's the same
            } else if withdrawn_start <= i && i < withdrawn_end {
                // i is in the withdrawn range: [pre.tail - buffer_size, new_tail - buffer_size)
                // These entries are removed from contents in post
                assert(!post.contents.contains_key(i));
                // Need to show they also don't satisfy the condition (left side is false, so right side must be false)
                // By pre.inv_buffer_contents with i in [pre.tail-buffer_size, pre.tail), we know:
                assert(pre.contents.contains_key(i));
                assert(pre.contents.contains_key(i) == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                                                        i < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))));
                // This tells us that in PRE state, the RIGHT side WAS true (because LEFT side is true)
                // But this isn't a contradiction - we're just removing those entries from contents in POST
                // What we need to show is that in POST state, the RIGHT side is FALSE, since LEFT side is FALSE (post.contents.contains_key(i) is false)
                // But wait, the alive_bits and map_min_value don't change in this operation!
                // So if in PRE state the RIGHT side was TRUE, it remains TRUE in POST state
                // This would indeed contradict our goal that they're equivalent.
                // Where am I going wrong?
                // 
                // Ah! Looking more closely at the invariant defn:
                // "forall |i: int| self.tail - self.buffer_size <= i < self.tail ==> (
                //    (log_entry_is_alive(self.alive_bits, i, self.buffer_size) ||
                //        i < map_min_value(self.local_versions, ((self.num_replicas - 1) as nat)))
                //    <=>
                //    #[trigger] self.contents.contains_key(i))"
                //
                // The invariant only applies for i IN THE CURRENT tail RANGE, that is:
                // i \in [post.tail - post.buffer_size, post.tail) = [new_tail - buffer_size, new_tail)
                //
                // Our case concerns i that is in [withdrawn_start, withdrawn_end) = [pre.tail - buffer_size, new_tail - buffer_size)
                // 
                // These two ranges may overlap, but importantly, i in our current case is NOT in the post.range 
                // whenever withdrawn_end <= post.tail_range_start, i.e., new_tail - buffer_size <= new_tail - buffer_size.
                // 
                // But they're equal, so elements in [pre.tail - buffer_size, new_tail - buffer_size) are EXACTLY those
                // elements that moved OUT of the valid range due to the tail increasing from pre.tail to new_tail
                // 
                // Actually, no! post.tail = new_tail, so post valid range is [new_tail - buffer_size, new_tail).
                // Our withdrawn range is [pre.tail - buffer_size, new_tail - buffer_size).
                // These are the same when pre.tail = new_tail, but we require pre.tail <= new_tail.
                // 
                // When pre.tail < new_tail, the withdrawn range is to the left of the post range.
                // In particular, for i in [pre.tail - buffer_size, new_tail - buffer_size), 
                // we have i < new_tail - buffer_size, so i IS NOT in the post.valid range.
                // 
                // Therefore, this case won't be triggered by the forall condition at all!
                // The assertion we're trying to prove only concerns i in [new_tail - buffer_size, new_tail)!
                assert(false); // This case should never happen due to quantification domain
            } else {
                // i >= withdrawn_end, and still within post range, so i is in [new_tail - buffer_size, new_tail)
                // But also must have i >= withdrawn_end = new_tail - buffer_size, which checks out.
                //
                // Subcases: 
                // 1. If i is in [new_tail - buffer_size, pre.tail), and we know i >= withdrawn_end = new_tail - buffer_size
                //    Also recall that withdrawn_end = new_tail - buffer_size, so we have i >= new_tail - buffer_size.
                //    And for this case to apply, we also need i < withdrawn_start = pre.tail - buffer_size
                //    So we need new_tail - buffer_size <= i < pre.tail - buffer_size
                //    This is non-empty iff new_tail < pre.tail (which contradicts requirement pre.tail <= new_tail)
                // 2. i is in [pre.tail, new_tail)
                //    Then we know i was not in pre.contents (since pre.contents indices are < pre.tail)  
                //    And it's also not in post.contents (as only deposits would add entries, not this transition)
                assert(!post.contents.contains_key(i));
                // In pre state, this i was not a content key, so pre invariant gave:
                assert(!pre.contents.contains_key(i));
                // But pre invariant only applies to i such that -buffer_size <= i < pre.tail
                // Here we have i >= pre.tail, so it might be outside the pre domain too.
                // Actually, no: we're under the assumption that this case applies, which means withdrawn_start <= i (to reach else branch)
                // And we saw that case 1 is impossible, so we must be in case 2: i >= pre.tail 
                // In which case, pre.contents.contains_key(i) is definitely false, as pre.contents.indices are < pre.tail
                // 
                // The pre invariant says that IF -pre.buffer_size <= i < pre.tail, THEN pre.contents.contains_key(i) is equivalent to the condition.
                // But our i satisfies i >= pre.tail, so the premise of that implication is false, so it gives us no information.
                // However, even if the premise were true (if we had i in [-buffer_size, pre.tail)), we'd know:
                assert forall |j: int| -pre.buffer_size <= j < pre.tail implies 
                              pre.contents.contains_key(j) == (log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) ||
                                                               j < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))) by {
                    // This is given by invariant
                };
                // But our i satisfies i >= pre.tail, so this doesn't help directly.
                // However, we know i is in [pre.tail, new_tail), and also in [new_tail - buffer_size, new_tail).
                // Together this means max(pre.tail, new_tail - buffer_size) <= i < new_tail
                // Since pre.tail <= new_tail, we have pre.tail <= i < new_tail.
                // This means in particular i >= pre.tail.
                // As noted, this means pre.contents.contains_key(i) = false.
                // 
                // Now, we want to show that also in POST,
                // (log_entry_is_alive(post.alive_bits, i, post.buffer_size) || i < map_min_value(...)) is false.
                // In POST, the relevant quantities have values:
                //  - alive_bits same as in pre (operation doesn't change alive_bits) 
                //  - local_versions same as in pre 
                //  - So we want to show: (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || i < map_min_value(pre.local_versions, ...)) is false.
                // 
                // We can't get this from the pre invariant because i is out of bounds for it. 
                // Is there another invariant that helps? 
                // The upcoming_bits_are_not_alive invariant seems promising!
                // It says that for i >= tail (which is currently pre.tail?), such entries are not alive.
                // But we're working with post at this point, whose tail = new_tail.
                // And we have i in [pre.tail, new_tail), so i < new_tail, so i is not >= tail (in post)
                // 
                // Hmm, let's check the upcoming_bits invariant in PRE...
                // upcoming_bits_are_not_alive says:
                // forall |i|
                //     self.tail <= i < min_local_head + self.buffer_size
                //     ==> !log_entry_is_alive(self.alive_bits, i, self.buffer_size)
                // 
                // In PRE: self.tail = pre.tail, so this says:
                // forall i, if pre.tail <= i < min_local_head + buffer_size, then !log_entry_is_alive(., i,.)
                // Our i satisfies i >= pre.tail. So if also i < min_local_head + buffer_size, we get that it's not alive.
                // We still need to handle the OTHER part of the disjunction though.
                assert(false); // Placeholder - proof not finished
            }
        };

        // For entries beyond tail, maintain the invariant that they don't exist
        assert forall |i: int| post.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
            // In POST, tail = new_tail, so contents.keys must be < new_tail
            // But that's exactly what's claimed!
        };

        // Maintain all_combiner_valid invariant  
        assert forall |n_id| #[trigger] post.combiner.contains_key(n_id) implies
            post.combiner_valid(n_id, post.combiner[n_id]) by {
            if n_id == node_id {
                // The combiner state changed for this node to Appending { cur_idx: pre.tail, tail: new_tail }
                assert(post.combiner[n_id] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });

                // Validate conditions for Appending state:
                // 1. self.local_versions[node_id] <= cur_idx <= tail 
                assert(post.local_versions.contains_key(node_id));
                assert(post.local_versions[node_id] <= pre.tail <= new_tail); 

                // 2. tail <= self.tail (after substitution: new_tail <= post.tail which equals new_tail) 
                assert(new_tail <= post.tail);

                // 3. (self.tail as int) - (self.buffer_size as int) <= cur_idx <= (self.tail as int)
                assert(((new_tail as int) - (post.buffer_size as int)) <= (pre.tail as int) <= (new_tail as int));

                // 4. All entries in [cur_idx, tail) = [pre.tail, new_tail) are not alive
                assert forall |i:nat| pre.tail <= i < new_tail implies 
                        !(log_entry_is_alive(post.alive_bits, i as int, post.buffer_size)) by {
                    // Use the same reasoning as in case 2 above about upcoming_bits_are_not_alive
                    assert(false); // Placeholder
                };

            } else {
                // Other combiner states remain unchanged
                assert(post.combiner[n_id] === pre.combiner[n_id]);
                assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
                assert(post.combiner_valid(n_id, post.combiner[n_id]));
            }
        };
    }

    #[inductive(append_flip_bit)]
    fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) { admit(); }

