#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    // Prove that inv_buffer_contents invariant is preserved
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // The post state has tail = new_tail, so we're checking the equivalence for i ∈ [new_tail - buffer_size, new_tail)

        // In the transition, we withdrew entries from the range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
        let withdraw_start = pre.tail - pre.buffer_size;
        let withdraw_end = new_tail - pre.buffer_size;

        // Note: pre.tail <= new_tail, so withdraw_start <= withdraw_end

        // Case analysis on where i falls:
        if i < withdraw_start {
            // i < pre.tail - pre.buffer_size, so i is in [-pre.buffer_size, pre.tail - pre.buffer_size)
            // Such entries are not affected by withdrawal
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            assert(map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)) == map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat)));
            // By pre invariant for the range [-pre.buffer_size, pre.tail):
            assert(pre.contents.contains_key(i) == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || 
                                                   i < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))));
            // Hence the same equivalence holds for post
        } else if i >= withdraw_end {
            // i >= new_tail - pre.buffer_size, and i < new_tail 
            // Combined: max(new_tail - pre.buffer_size, pre.tail - pre.buffer_size) <= i < new_tail
            // Since pre.tail <= new_tail, we have pre.tail - pre.buffer_size <= new_tail - pre.buffer_size
            // So the max is new_tail - pre.buffer_size
            // Thus: new_tail - pre.buffer_size <= i < new_tail
            // Also, since i >= new_tail - pre.buffer_size, we have i + pre.buffer_size >= new_tail, so i >= new_tail - pre.buffer_size

            // These entries (in [new_tail - pre.buffer_size, new_tail)) were not affected by withdrawal
            // because the withdrawal interval is [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            assert(map_min_value(post.local_versions, ((post.num_replicas - 1) as nat)) == map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat)));
            // Now, we need to determine whether pre.contents.contains_key(i) holds.
            // Recall that pre.contents has indices in [-pre.buffer_size, pre.tail).
            // 
            // Our i is in [new_tail - pre.buffer_size, new_tail).
            // We distinguish subcases based on relationship between new_tail and pre.tail:
            // 
            // Subcase 1: new_tail <= pre.tail  
            // Then i < new_tail <= pre.tail, so i < pre.tail. Combined with i >= new_tail - pre.buffer_size,
            // we have new_tail - pre.buffer_size <= i < pre.tail.
            // Whether this overlaps with [-pre.buffer_size, pre.tail) depends on whether new_tail - pre.buffer_size >= -pre.buffer_size,
            // i.e., new_tail >= 0, which is guaranteed as new_tail is nat.
            // So i is in [max(new_tail - pre.buffer_size, -pre.buffer_size), pre.tail) = [new_tail - pre.buffer_size, pre.tail)
            // (assuming new_tail <= pre.buffer_size; if not, it's [-pre.buffer_size, pre.tail)).
            // Either way, if i is in the domain of pre.contents, then by the pre invariant:
            assert forall |j: int| new_tail - pre.buffer_size <= j < pre.tail implies 
                           pre.contents.contains_key(j) == (log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) ||  
                                                            j < map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))) by {
                // Direct application of pre invariant (range [-pre.buffer_size, pre.tail))
            };
            // Hence, the equivalence transfers to post for such j.

            // Subcase 2: new_tail > pre.tail
            // Then since i >= new_tail - pre.buffer_size, we get i >= new_tail - pre.buffer_size > pre.tail - pre.buffer_size.
            // Also i < new_tail and we're checking the domain of pre.contents which is < pre.tail.
            // So if new_tail > pre.tail, and i < new_tail but also i must satisfy i >= new_tail - pre.buffer_size,
            // we ask: can we have both i < pre.tail and i >= new_tail - pre.buffer_size when new_tail > pre.tail?
            // I.e., is there overlap between (-∞, pre.tail) and [new_tail - pre.buffer_size, new_tail)?
            // Yes, if pre.tail > new_tail - pre.buffer_size, i.e., 2*pre.tail > new_tail.
            // Specifically, intersection is [new_tail - pre.buffer_size, pre.tail).
            // Otherwise, if pre.tail <= new_tail - pre.buffer_size (i.e., 2*pre.tail <= new_tail), no overlap.
            // In case of overlap, we apply the pre invariant as in subcase 1.
            // In case of no overlap, we have i >= pre.tail, hence not in pre.contents.domain
        } else {
            // withdraw_start <= i < withdraw_end
            // i.e., pre.tail - pre.buffer_size <= i < new_tail - pre.buffer_size 
            // These entries were explicitly withdrawn from pre.contents, so they're not in post.contents
            assert(!post.contents.contains_key(i));
            // We must show the left-hand side of the equivalence is also false in post
            // Left-hand side is: (log_entry_is_alive(post.alive_bits, i, post.buffer_size) || i < map_min_value(...))
            // Since alive_bits and local_versions unchanged, this equals:  
            // (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) || i < map_min_value(pre.local_versions, ...))
            // By the pre invariant (for i in [-pre.buffer_size, pre.tail)), this expression is equivalent
            // to pre.contents.contains_key(i). But we're considering i such that pre.contents.contains_key(i) was true
            // (before withdrawal) and is now false (in post.contents). So we seem to have a contradiction!
            // 
            // Resolution: Note that the pre invariant is only assumed for i in [-pre.buffer_size, pre.tail).
            // For such i, we indeed have that in PRE state, contents.contains_key(i) <=> (condition).
            // After withdrawal, contents.contains_key(i) becomes false, but the RHS remains the same.
            // Does this mean the invariant is violated? No, because in the POST state, the invariant is only claimed
            // for i in [post.tail - post.buffer_size, post.tail) = [new_tail - buffer_size, new_tail).
            // 
            // The question is: Do values i satisfying withdraw_start <= i < withdraw_end fall into the new invariant domain?
            // New domain is [new_tail - buffer_size, new_tail).
            // Our range is [pre.tail - pre.buffer_size, new_tail - pre.buffer_size).
            // These are disjoint because: new_tail - pre.buffer_size <= new_tail - buffer_size implies pre.buffer_size >= 0, OK.
            // And pre.tail - pre.buffer_size >= new_tail - buffer_size implies pre.tail >= new_tail - buffer_size + pre.buffer_size = new_tail?? No,
            // new_tail - buffer_size + pre.buffer_size = new_tail + (pre.buffer_size - buffer_size). Since buffer_size = pre.buffer_size (constant)
            // this is just new_tail.
            // So condition is pre.tail >= new_tail. If true, overlap at [pre.tail, new_tail - pre.buffer_size).
            // If false, no overlap.
            // But we're assuming pre.tail <= new_tail, so pre.tail <= new_tail, and equality only when pre.tail = new_tail.
            // If pre.tail = new_tail, then no withdrawal, and we wouldn't be in this branch. Contradiction.
            // Wait, let's recheck: branch is i >= withdraw_start (i.e., i >= pre.tail - pre.buffer_size) and i < withdraw_end (i < new_tail - pre.buffer_size)
            // This is satisfiable only if pre.tail - pre.buffer_size < new_tail - pre.buffer_size, i.e., pre.tail < new_tail. OK.
            // The NEW domain is [new_tail - buffer_size, new_tail).
            // The WITHDRAWN indices are [pre.tail - pre.buffer_size, new_tail - pre.buffer_size).
            // These intervals: 
            //  NEW = [new_tail - buffer_size, new_tail) 
            //  OLD = [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
            // Do they intersect? 
            // Intersection requires max(new_tail - buffer_size, pre.tail - pre.buffer_size) <= min(new_tail, new_tail - pre.buffer_size)
            // Note min(new_tail, new_tail - pre.buffer_size) = new_tail - pre.buffer_size (since pre.buffer_size > 0)
            // So we need max(new_tail - buffer_size, pre.tail - pre.buffer_size) <= new_tail - pre.buffer_size
            // Which is true iff new_tail - buffer_size <= new_tail - pre.buffer_size, that is, pre.buffer_size <= buffer_size.
            // This is true since buffer_size = pre.buffer_size (constants don't change). Even equality holds.
            // So max = new_tail - pre.buffer_size, condition becomes new_tail - pre.buffer_size <= new_tail - pre.buffer_size. ✓ (equality)
            // Therefore, the intersection IS exactly the endpoint new_tail - pre.buffer_size, meaning singleton {new_tail - pre.buffer_size}
            // is shared only when new_tail - pre.buffer_size = new_tail - buffer_size, implying buffer_size = pre.buffer_size.
            // But all constants are equal. So we can simplify: buffer_size = LOG_SIZE throughout.
            // 
            // Actually, I think I'm overcomplicating this.
            // In this third case, we have i in [pre.tail - pre.buffer_size, new_tail - pre.buffer_size).
            // We want to show that for such i, in the POST state, i does NOT belong to [new_tail - buffer_size, new_tail).
            // Because if it doesn't belong, THEN the invariant doesn't constrain it at all.
            // 
            // We want NOT(new_tail - buffer_size <= i < new_tail). It suffices to show either i < new_tail - buffer_size or i >= new_tail.
            // From the case condition, i < new_tail - pre.buffer_size.
            // If buffer_size = pre.buffer_size, then new_tail - buffer_size = new_tail - pre.buffer_size.
            // So we have i < new_tail - pre.buffer_size = new_tail - buffer_size. Done.
            assert(false); // Contradictory - case shouldn't apply 
        }
    };

    // Prove that all_combiner_valid invariant is preserved
    assert forall |n_id| #[trigger] post.combiner.contains_key(n_id) implies
        post.combiner_valid(n_id, post.combiner[n_id]) by {
        if n_id == node_id {
            // Node n_id's combiner changed to Appending { cur_idx: pre.tail, tail: new_tail }
            assert(post.combiner[n_id] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });

            // Check conditions for CombinerState::Appending validity:
            // 1. self.local_versions[node_id] <= cur_idx <= tail
            assert(post.local_versions.contains_key(node_id));
            assert(post.local_versions[node_id] <= pre.tail <= new_tail); 

            // 2. tail <= self.tail 
            assert(new_tail <= post.tail);
            assert(post.tail == new_tail);

            // 3. (self.tail as int) - (self.buffer_size as int) <= cur_idx <= (self.tail as int)
            assert((new_tail as int) - (post.buffer_size as int) <= pre.tail <= (new_tail as int));

            // 4. All entries in [cur_idx, tail) = [pre.tail, new_tail) are not alive
            assert forall |j: nat| pre.tail <= j < new_tail implies 
                !(log_entry_is_alive(post.alive_bits, j as int, post.buffer_size)) by {
                // Rely on the invariant that entries ahead of tail are not alive
                // Specifically, pre.upcoming_bits_are_not_alive states:
                //  forall |i| pre.tail <= i < min_local_head + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
                // where min_local_head = map_min_value(pre.local_versions, ((pre.num_replicas - 1) as nat))
                // 
                // So for j with pre.tail <= j < new_tail, we need to guarantee j < min_local_head + pre.buffer_size to apply the invariant.
                // This holds if new_tail <= min_local_head + pre.buffer_size.
                // Now, from pre.all_combiner_valid, we know that for the previous state, invariants hold.
                // The requirement for advance_tail_finish is that pre.tail <= new_tail <= observed_head + pre.buffer_size
                // where observed_head = pre.head.
                // Additionally, from pre.pointer_ordering: pre.head <= pre.local_versions[n] for all n.
                // Therefore, observed_head = pre.head <= min_local_head.
                // So we expect new_tail <= observed_head + pre.buffer_size <= min_local_head + pre.buffer_size.
                // Hence, our j in [pre.tail, new_tail) satisfy j < new_tail <= min_local_head + pre.buffer_size,
                // and we can apply the pre.upcoming_bits_are_not_alive invariant.
                assert(log_entry_is_alive(post.alive_bits, j as int, post.buffer_size) == log_entry_is_alive(pre.alive_bits, j as int, pre.buffer_size));
                assert(!log_entry_is_alive(pre.alive_bits, j as int, pre.buffer_size));
            };
        } else {
            // Other nodes' combiner states unchanged
            assert(post.combiner[n_id] === pre.combiner[n_id]);
            assert(pre.combiner_valid(n_id, pre.combiner[n_id]));
            assert(post.combiner_valid(n_id, post.combiner[n_id]));
        }
    };
}

